import React, { Component } from 'react'
import { connect } from 'react-redux'
import { Button, Col, Icon, Row, Upload } from 'antd'
import TableWrapper from '../pagination.style'
import CircularLoader from '../../../../components/CircularLoader'
import LayoutContentStyle from '../../../../components/utility/layoutContent'
import { PolicyExtraCommissionStyle } from './index.style'
import { get } from 'lodash'
import agentAction from '../../../redux/agent/actions'
import policyActions from '../../../../redux/policy/actions'
import { showNotification } from '../../../../components/ShowNotification'
import moment from 'moment'

const { getPolicyExcelsList, uploadPolicyExcels, resetAgentRedux } = agentAction
const { uploadPolicyFile, resetReduxState } = policyActions
class PolicyExtraCommission extends Component {
  state = {
    page: 1
  }

  componentDidMount () {
    this.fetchPolicyExcelsList()
  }

  componentDidUpdate () {
    const {
      uploadPolicyFileData = {}, resetReduxState, extraCommissionUploadFileStatus,
      resetAgentRedux
    } = this.props
    if (get(uploadPolicyFileData, 'url', '')) {
      this.props.uploadPolicyExcels({
        file_url: get(uploadPolicyFileData, 'url', '')
      })
      resetReduxState(['uploadPolicyFileData'])
    }

    if (extraCommissionUploadFileStatus === 'success') {
      showNotification('success', 'File Uploaded successfully!')
      this.fetchPolicyExcelsList()
      resetAgentRedux(['extraCommissionUploadFileStatus'])
    } else if (extraCommissionUploadFileStatus) {
      showNotification('error', 'Sorry, We are facing some issue. Please tey again!')
      resetAgentRedux(['extraCommissionUploadFileStatus'])
    }
  }

  handleTableChange = (pagination) => {
    const { pageSize, current } = pagination
    const finalFilter = {
      page: current,
      page_size: pageSize
    }
    this.setState({
      page: current
    }, () => {
      this.fetchPolicyExcelsList(finalFilter)
    })
  }

  fetchPolicyExcelsList = (queryObject = {}) => {
    this.props.getPolicyExcelsList({
      page: this.state.page,
      page_size: 10,
      ...queryObject
    })
  }

  extraDetailDocumentUpload = ({ file }) => {
    const formData = new FormData()
    const [name, ext] = file.name ? file.name.split('.') : ['']
    const fileName = `${name.replace(/[' ']/g, '-')}-${Date.now()}`
    formData.append('file', file, `${fileName}.${ext}`)
    formData.append('path', `insurance-policy-certificate-control-panel/${fileName}`)
    formData.append('identifier', 'agent')
    this.props.uploadPolicyFile({ body: formData })
  }

  getColumns = () => {
    return [
      {
        key: 'name',
        title: 'File Name',
        dataIndex: 'file_name',
        align: 'center'
      },
      {
        key: 'uploaded_by',
        title: 'Uploaded By',
        dataIndex: 'uploaded_by',
        align: 'center'
      },
      {
        key: 'date',
        title: 'Date',
        dataIndex: 'created_at',
        render: (date) => moment(date).format('YYYY-MM-DD'),
        align: 'center'
      },
      {
        key: 'status',
        title: 'Status',
        dataIndex: 'status',
        align: 'center'
      },
      {
        key: 'download',
        title: 'Download',
        dataIndex: 'uploaded_url',
        align: 'center',
        render: (item, props) => {
          return (
            <Row type='flex' align='middle' justify='space-around'>
              <Col>
                <Button type='link' href={props.uploaded_url}>
                  <Icon type='cloud-download' />&nbsp;&nbsp;All
                </Button>
              </Col>
              {
                props.failed_doc_url && (
                  <Col>
                    <Button type='link' href={props.failed_doc_url}>
                      <Icon type='cloud-download' />&nbsp;&nbsp;Failed
                    </Button>
                  </Col>
                )
              }
            </Row>
          )
        }
      }
    ]
  }

  render () {
    const {
      excelUploadLoader, policyExcelsData, policyExcelListLoader,
      uploadGenericLoader
    } = this.props
    const { page } = this.state
    return (
      <CircularLoader isSpining={policyExcelListLoader || excelUploadLoader || uploadGenericLoader}>
        <PolicyExtraCommissionStyle>
          <LayoutContentStyle>
            <h3>Add Extra Payment Data</h3>
            <Row type='flex' align='middle' justify='center'>
              <Col sm={8} xm={8} xl={5}>
                <Upload
                  showUploadList={false}
                  accept='.xlsx,.xls'
                  customRequest={fileData => this.extraDetailDocumentUpload(fileData)}
                >
                  <Button>
                    <Icon type='cloud-upload' />&nbsp;&nbsp;Upload The Excel
                  </Button>
                </Upload>
              </Col>
              <Col sm={8} xm={8} xl={5}>
                <Button href={policyExcelsData.sample_doc_url}>
                  <Icon type='cloud-download' />&nbsp;&nbsp;Download Sample Excel
                </Button>
              </Col>
            </Row>
            <br /><br />
            <TableWrapper
              columns={this.getColumns()}
              bordered
              rowKey={record => record.id}
              dataSource={get(policyExcelsData, 'data', [])}
              pagination={{
                pageSize: 10,
                total: get(policyExcelsData, 'meta_data.total_records', 0),
                current: page
              }}
              loading={policyExcelListLoader}
              onChange={this.handleTableChange}
              className='isoSearchableTable agent-table-data'
            />
          </LayoutContentStyle>
        </PolicyExtraCommissionStyle>
      </CircularLoader>
    )
  }
}

export default connect(
  state => ({
    excelUploadLoader: state.Loading.UPLOAD_POLICY_EXCELS,
    uploadGenericLoader: state.Loading.UPLOAD_FILE,
    uploadPolicyFileStatus: state.Insurance.uploadPolicyFileStatus,
    uploadPolicyFileData: state.Insurance.uploadPolicyFileData,
    policyExcelListLoader: state.Loading.GET_POLICY_EXCELS_LIST,
    policyExcelsData: state.Agent.policyExcelsData,
    policyExcelsMetaData: state.Agent.policyExcelsMetaData,
    policyExcelsStatus: state.Agent.policyExcelsStatus,
    extraCommissionUploadFileData: state.Agent.extraCommissionUploadFileData,
    extraCommissionUploadFileStatus: state.Agent.extraCommissionUploadFileStatus
  }),
  {
    getPolicyExcelsList,
    resetReduxState,
    resetAgentRedux,
    uploadPolicyExcels,
    uploadPolicyFile
  }
)(PolicyExtraCommission)
